import{_ as e,o as i,c as n,ah as a}from"./chunks/framework.D4KxWb5R.js";const m=JSON.parse('{"title":"Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"guide/administration/settings.md","filePath":"src/guide/administration/settings.md"}'),r={name:"guide/administration/settings.md"};function s(o,t,d,u,l,c){return i(),n("div",null,[...t[0]||(t[0]=[a('<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h1><p>Les réglages de gestion de M&#39;City se modifient depuis le back-office, sans intervention d&#39;edPage. Réservé au PDG. Chaque modification s&#39;applique immédiatement et est inscrite au <a href="./logs.html">journal d&#39;administration</a>, avec son auteur, sa date, l&#39;ancienne et la nouvelle valeur.</p><h2 id="parametres" tabindex="-1">Paramètres <a class="header-anchor" href="#parametres" aria-label="Permalink to &quot;Paramètres&quot;">​</a></h2><p><strong>Administration → Configuration</strong> :</p><table tabindex="0"><thead><tr><th>Paramètre</th><th>Par défaut</th><th>Effet</th></tr></thead><tbody><tr><td>Validité des invitations (jours)</td><td>7</td><td>Durée pendant laquelle un mot de passe temporaire fonctionne, fixée à l&#39;envoi.</td></tr><tr><td>Déconnexion après inactivité (minutes)</td><td>30</td><td>Les sessions de l&#39;intranet et du back-office se ferment après cette durée sans activité.</td></tr><tr><td>Longueur minimale des mots de passe</td><td>12</td><td>S&#39;applique à tout nouveau mot de passe ; 8 au minimum.</td></tr><tr><td>Exiger l&#39;authentification à deux facteurs pour tous</td><td>Non</td><td>Chaque compte reçoit un code par e-mail à la connexion, sauf s&#39;il utilise une application d&#39;authentification ou une passkey. Elle peut aussi être exigée compte par compte.</td></tr><tr><td>Langue des nouveaux comptes</td><td>Anglais</td><td>Proposée à la création d&#39;un compte.</td></tr><tr><td>Tentatives de resynchronisation</td><td>5</td><td>Nombre d&#39;envois d&#39;une fiche au back-office d&#39;un produit avant de le déclarer désynchronisé (entre 1 et 20).</td></tr><tr><td>Fenêtre d&#39;activité (jours)</td><td>30</td><td>Fenêtre glissante d&#39;un « utilisateur actif », sauf si un indicateur fixe la sienne.</td></tr><tr><td>Remontée des indicateurs</td><td>Envoi par le produit</td><td>Mode par défaut des produits ; chaque produit peut en changer sur sa page d&#39;intégration.</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Code par e-mail</p><p>Avec la double authentification par e-mail, la connexion dépend de l&#39;envoi des e-mails : si les e-mails de M&#39;City IQ ne partent plus, ces comptes ne peuvent plus se connecter.</p></div><h2 id="definitions-d-indicateurs" tabindex="-1">Définitions d&#39;indicateurs <a class="header-anchor" href="#definitions-d-indicateurs" aria-label="Permalink to &quot;Définitions d&#39;indicateurs&quot;">​</a></h2><p><strong>Administration → Indicateurs</strong> liste les indicateurs consolidés et les produits qui les remontent. Un indicateur s&#39;ajoute sans développement, à condition que le produit sache le fournir.</p><ol><li><strong>Nouvel indicateur</strong> (ou ouvrez un indicateur).</li><li><strong>Clé</strong> : identifiant attendu des produits (minuscules, chiffres, <code>_</code>). Elle ne change plus après la création.</li><li><strong>Libellé</strong>, en anglais et en français.</li><li><strong>Agrégation</strong> : décompte distinct, somme ou ratio. Seule une somme s&#39;additionne entre produits.</li><li><strong>Fenêtre (jours)</strong> : vide pour reprendre la fenêtre d&#39;activité de la configuration.</li><li><strong>Produits sources</strong> : seuls ces produits peuvent remonter l&#39;indicateur.</li><li><strong>Actif</strong> : un indicateur inactif n&#39;est plus accepté ni affiché ; ses valeurs sont conservées.</li></ol><p>Prévenez l&#39;équipe du produit : elle doit exposer l&#39;indicateur, par l&#39;API ou sur son point de relevé (voir <a href="./../integration/indicators.html">Indicateurs</a>).</p>',10)])])}const f=e(r,[["render",s]]);export{m as __pageData,f as default};
